#!/usr/bin/env python3
"""Summary evaluation cost, including explicit refresh cost; local static report."""
import csv
import json
from pathlib import Path
import sys
root=Path(sys.argv[1]) if len(sys.argv)>1 else Path('artifacts/appearance-probe/cost')
data=json.loads((root/'report.json').read_text());assert data['schema']==1
rows=[]
for r in data['cases']:
    for m in r['methods']:
        row=dict(scene=r['case'],frame=r['frame'],distance=r['parameters']['distance'],profile=m['profile'],triangles=m['triangles'],active_nodes=m['active_nodes'],prepared=m['prepared'],cpu_us=m['cpu_us'],queue_us=m['queue_us'],max_linear_delta=m['delta']['max_abs'],alpha_delta=m['delta']['alpha_rmse'],rmse=m['error']['rmse_surface'])
        for k in ['before','after','full','unreduced','cold']:row[k+'_ms']=m[k]['gpu_ms_median']
        row['preparation_ms']=m['cold']['preparation_ms_median'];rows.append(row)
with (root/'results.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
page=r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ignis · Custo dos resumos</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0d1219;color:#e8eef7}body{max-width:1380px;margin:auto;padding:30px 24px}h1{font-size:38px;letter-spacing:-1px;margin:12px 0}h2{font-size:22px}p{line-height:1.65;color:#b6c5d5;max-width:1140px}.tag{color:#ffae62;font-size:12px;letter-spacing:2px}.box{background:#151e2a;border:1px solid #304158;border-radius:12px;padding:20px;margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:center}.controls+.controls{margin-top:20px}select,button{font:inherit;background:#26364b;border:1px solid #455c77;border-radius:6px;padding:8px;color:inherit}input[type=range]{min-width:200px;flex:1;accent-color:#ffae62}label{font-size:14px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}figure{margin:0}canvas{width:100%;max-width:256px;border:1px solid #34455c;background:#20252d;border-radius:6px}figcaption{font-size:14px;line-height:1.5;margin-top:9px}.small{font-size:12px;color:#afc2d9;line-height:1.7}.stats{display:flex;flex-wrap:wrap;gap:28px}.stats b{display:block;color:#fff;font-size:26px}.stats span{font-size:13px;color:#b6c5d5}a{color:#ffae62}.note{border-left:3px solid #ffae62;padding-left:15px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:right;padding:9px;border-bottom:1px solid #34455c}th:first-child,td:first-child{text-align:left}summary{cursor:pointer}svg{width:100%}code{color:#ffcf9e}@media(max-width:950px){.grid{grid-template-columns:1fr 1fr}h1{font-size:28px}}@media(max-width:500px){.grid{grid-template-columns:1fr}}
</style><div class="tag">IGNIS / PESQUISA GRÁFICA / EAF-68</div><h1>Avaliar uma vez. Reutilizar no desenho.</h1>
<p>A mesma seleção e a mesma transição gradual, com os resumos calculados por região e reutilizados enquanto luz, direção da visão e parâmetros de iluminação permanecerem iguais. Cada mudança dessas entradas exige uma atualização, cujo custo aparece separado abaixo.</p>
<div class="box"><div class="controls"><label>Cena <select id="scene"><option value="diffuse">Difusa ·35°</option><option value="glossy" selected>Brilhante ·35°</option><option value="grazing">Rasante ·75°</option><option value="transition">Movimento fino ·10–11</option></select></label><button id="play">Reproduzir ida e volta</button><button id="back" aria-label="Frame anterior">←</button><button id="next" aria-label="Próximo frame">→</button><label><input id="zoom" type="checkbox"> Ampliar objeto</label><label><input id="pixels" type="checkbox"> Grade de pixels</label></div>
<div class="controls"><label for="quality">Mais resumos</label><input type="range" id="quality" min="0" max="2" step="1" value="0"><label for="quality">Mais geometria</label><strong id="profile"></strong></div>
<div class="controls"><label for="frame">Câmera</label><input type="range" id="frame" min="0" value="16"><span id="position"></span></div><p id="pose" aria-live="polite"></p><div id="stats" class="stats"></div></div>
<div class="grid" id="images"></div><p class="note" id="identity"></p>
<div class="box"><h2>Custo nesta posição</h2><div id="table"></div><p id="cpu"></p><p>“Atualização + desenho” inclui a avaliação dos resumos, a sincronização e o desenho. “Reutilizado” só se aplica quando as entradas da radiância continuam iguais. Não descontamos o custo de uma mudança de luz ou de ângulo como se fosse gratuito.</p></div>
<div class="box"><h2>Quando a redução de triângulos se traduz em ganho</h2><div id="chart"></div><p id="result"></p></div>
<details class="box"><summary><b>Fidelidade, validade da reutilização e método de medição</b></summary><p>A ordem das misturas e a transformação da altura continuam iguais. Ligações diretas pulam apenas ancestrais com peso zero. Nenhuma tolerância de seleção foi relaxada. A comparação verifica RGB linear e cobertura antes de converter para PNG; o erro contra a referência integrada permanece visível no quarto painel. As limitações anteriores de cobertura, oclusão e reflexos rasantes continuam existentes.</p>
<p>Este modelo usa luz e direção de visão uniformes sobre o objeto. Mover a câmera apenas em distância mantém a radiância dos resumos válida; orbitar a câmera ou mudar a luz a invalida. Essa condição não se transfere automaticamente para iluminação local, sombras ou GI. Cada malha enviada possui armazenamento próprio; mudanças de distribuição exigem novo upload. O benchmark mostra também o custo de recalcular todos os resumos em cada frame.</p>
<p>Cinco métodos são intercalados em31 rodadas, com rotação da ordem, após aquecimento de todos. O controle completo usa um shader direto. “Mesma aparência sem reduzir” mantém os65.536 triângulos e os mesmos pesos de transição; pequenas diferenças de cobertura por triangulação já foram documentadas. A medição de atualização começa no compute e termina após o draw, incluindo o intervalo entre passes. Variações de frequência/carga da GPU ainda afetam os números.</p>
<p>Tempos GPU são nativos de256²/uma amostra por pixel. Imagens usam128amostras, referência2.048. Seleção CPU, validação/envio, readback e PNG são separados; não converta esses tempos isolados em FPS de gameplay. A interface reproduz capturas pré-calculadas; a integração na engine ainda precisará compartilhar operação MCP/UI.</p></details>
<p><a href="report.json">Dados JSON e testes de invalidação</a> · <a href="results.csv">CSV</a> · <a href="../quality/index.html">Estudo anterior de qualidade</a></p><p id="metadata" class="small"></p><p class="small">Reproduzir: <code>cargo run --locked --release --example appearance_probe -- --summary-cost</code> e <code>python3 scripts/report_summary_cost.py</code>.</p>
<script>
const data=__DATA__,$=id=>document.getElementById(id),fmt=(x,n=5)=>x==null?'indisponível':x.toFixed(n),series=()=>data.cases.filter(r=>r.case===$('scene').value);let timer=null,request=0;const cache=new Map();
function stop(){clearInterval(timer);timer=null;$('play').textContent='Reproduzir ida e volta'}
function load(src){if(cache.has(src))return cache.get(src);const p=new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>{cache.delete(src);reject(Error('Imagem indisponível: '+src))};img.src=src});cache.set(src,p);while(cache.size>48)cache.delete(cache.keys().next().value);return p}
function canvas(img,r,title){const c=document.createElement('canvas');c.width=c.height=256;c.setAttribute('role','img');c.setAttribute('aria-label',title);const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;let x=0,y=0,w=256;if($('zoom').checked){const b=r.screen_bounds;w=Math.min(256,Math.ceil(Math.max(b[2]-b[0],b[3]-b[1]))+6);x=Math.max(0,Math.min(256-w,Math.floor((b[0]+b[2]-w)/2)));y=Math.max(0,Math.min(256-w,Math.floor((b[1]+b[3]-w)/2)))}ctx.drawImage(img,x,y,w,w,0,0,256,256);if($('pixels').checked&&$('zoom').checked&&w<90){ctx.strokeStyle='rgba(255,255,255,.2)';ctx.lineWidth=.5;ctx.beginPath();for(let i=0;i<=w;i++){const p=i*256/w;ctx.moveTo(p,0);ctx.lineTo(p,256);ctx.moveTo(0,p);ctx.lineTo(256,p)}ctx.stroke()}return c}
async function show(){const ticket=++request,rows=series();$('frame').max=rows.length-1;const i=Math.min(Number($('frame').value),rows.length-1),r=rows[i],profile=Number($('quality').value),m=r.methods.find(m=>m.profile===profile);
try{const figures=await Promise.all([['reference','Referência integrada'],['after','Resumos reutilizados'],['before','Gradual anterior'],['error','Erro contra referência ×8']].map(async([method,title])=>{const file=r.id+(method==='reference'?'_reference':`_p${profile}_${method}`)+'.png',img=await load(file),fig=document.createElement('figure');fig.append(canvas(img,r,title));const caption=document.createElement('figcaption');caption.textContent=title;fig.append(caption);return fig}));if(ticket!==request)return;$('images').replaceChildren(...figures)}catch(e){if(ticket===request)$('pose').textContent=e.message;return}
$('profile').textContent=data.profiles[profile].name;$('position').textContent=`${i+1}/${rows.length}`;$('pose').textContent=`${i<=r.turn?'AFASTANDO':'APROXIMANDO'} · distância ${r.parameters.distance.toFixed(3)} · ${r.parameters.tilt}°`;
$('stats').innerHTML=[[m.triangles.toLocaleString('pt-BR'),'triângulos'],[fmt(m.after.gpu_ms_median,4)+'ms','GPU · reutilizado'],[fmt(m.full.gpu_ms_median,4)+'ms','GPU · geometria completa'],[fmt(m.cold.gpu_ms_median,4)+'ms','GPU · atualização + desenho']].map(([v,t])=>`<span><b>${v}</b>${t}</span>`).join('');
$('identity').textContent=`Diferença máxima antes/depois em RGB linear: ${m.delta.max_abs.toExponential(2)}; diferença de cobertura: ${m.delta.alpha_rmse.toExponential(2)}. RMSE contra referência: ${fmt(m.error.rmse_surface)}. O objetivo desta otimização é conservar a aparência anterior, inclusive sua transição.`;
const methods=[['before','Gradual anterior'],['after','Otimizado · reutilizado'],['cold','Otimizado · atualização + desenho'],['full','Geometria completa'],['unreduced','Mesma aparência sem reduzir']];$('table').innerHTML='<table><tr><th>Método</th><th>GPU total ms</th><th>p10–p90 ms</th><th>Compute ms</th><th>Draw ms</th></tr>'+methods.map(([key,label])=>{const t=m[key];return `<tr><td>${label}</td><td>${fmt(t.gpu_ms_median,4)}</td><td>${fmt(t.gpu_ms_p10,4)}–${fmt(t.gpu_ms_p90,4)}</td><td>${fmt(t.preparation_ms_median,4)}</td><td>${fmt(t.draw_ms_median,4)}</td></tr>`}).join('')+'</table>';
$('cpu').textContent=`Seleção CPU: ${fmt(m.cpu_us,1)}µs. Validação/envio: ${fmt(m.queue_us,1)}µs. Resumos com peso positivo: ${m.active_nodes.toLocaleString('pt-BR')}. Esta pose ${m.prepared?'precisou atualizar':'reutilizou ou dispensou'} os valores na primeira captura. A seleção CPU ainda pode dominar o tempo total.`;
const ratio=m.after.gpu_ms_median/m.full.gpu_ms_median,unreduced=m.after.gpu_ms_median/m.unreduced.gpu_ms_median;$('result').textContent=`Nesta medição, reutilizado/completo = ${fmt(ratio,2)}× e reduzido/sem reduzir = ${fmt(unreduced,2)}×. Valores abaixo de1 indicam menor tempo GPU; acima de1 indicam regressão. Ganho não é universal, especialmente quando há atualização frequente.`;
const W=1000,H=240,L=65,R=25,T=15,B=30,X=j=>L+j/(rows.length-1)*(W-L-R),Y=v=>T+(1-Math.min(v,2)/2)*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Razão de tempo GPU otimizado sobre geometria completa, por pose">`;for(const v of [0,1,2])svg+=`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="${v===1?'#dce6f2':'#35465a'}"/><text x="8" y="${Y(v)+4}" fill="#b6c5d5" font-size="12">${v}×</text>`;for(const [j,color] of [[0,'#ffad57'],[1,'#62beff'],[2,'#a6d77a']])svg+=`<polyline points="${rows.map((q,k)=>{const a=q.methods.find(m=>m.profile===j);return X(k)+','+Y(a.after.gpu_ms_median/a.full.gpu_ms_median)}).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`;svg+=`<circle cx="${X(i)}" cy="${Y(ratio)}" r="5" fill="white"/>`;$('chart').innerHTML=svg+'</svg><p class="small">Abaixo de1×: menor tempo GPU que a geometria completa. Laranja: mais resumos · azul: intermediário · verde: mais geometria. Eixo horizontal: ida e volta; valores acima de2× são cortados apenas no gráfico.</p>';
}
function step(d){$('frame').value=(Number($('frame').value)+d+series().length)%series().length;show()}
for(const id of ['scene','zoom','pixels'])$(id).onchange=()=>{stop();show()};for(const id of ['quality','frame'])$(id).oninput=()=>{stop();show()};$('back').onclick=()=>{stop();step(-1)};$('next').onclick=()=>{stop();step(1)};$('play').onclick=()=>{if(timer)stop();else{$('play').textContent='Pausar';timer=setInterval(()=>step(1),350)}};
$('metadata').textContent=`${data.adapter} · ${data.cases.length} poses ×3perfis · ${data.cache_checks.length} verificações de cache/invalidação · ${(data.evaluated_bytes/1024).toFixed(1)}KiB adicionais de radiância GPU · ${data.seconds.toFixed(1)}s de execução offline. Interação nativa e aceite visual separados.`;show();
</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')));print(root/'index.html')
try:
    from PIL import Image,ImageDraw,ImageFont
except ImportError:
    pass
else:
    out=Image.new('RGB',(1280,1090),'#101722');draw=ImageDraw.Draw(out);font=ImageFont.truetype('/System/Library/Fonts/Supplemental/Arial.ttf',18);small=ImageFont.truetype('/System/Library/Fonts/Supplemental/Arial.ttf',15)
    draw.text((24,20),'IGNIS / custo menor, mesma transição',font=font,fill='#e8eef7')
    draw.text((24,55),'RGB linear e cobertura comparados antes/depois; erro no último painel é contra a referência.',font=small,fill='#b6c5d5')
    for row,frame in enumerate([9,16,21]):
        r=next(r for r in data['cases'] if r['case']=='glossy' and r['frame']==frame);m=next(m for m in r['methods'] if m['profile']==0)
        b=r['screen_bounds'];side=min(256,int(max(b[2]-b[0],b[3]-b[1]))+7);x=max(0,min(256-side,int((b[0]+b[2]-side)/2)));y=max(0,min(256-side,int((b[1]+b[3]-side)/2)));yy=100+row*325
        draw.text((24,yy),f'Distância {r["parameters"]["distance"]:.2f} / {m["triangles"]:,} triângulos / GPU reutilizado {m["after"]["gpu_ms_median"]:.4f}ms',font=font,fill='#ffad57')
        for col,(method,label) in enumerate([('reference','Referência'),('p0_after','Otimizado'),('p0_before','Anterior'),('p0_error','Erro contra referência ×8')]):
            img=Image.open(root/(r['id']+'_'+method+'.png')).crop((x,y,x+side,y+side)).resize((250,250),Image.Resampling.NEAREST);xx=24+col*312;out.paste(img,(xx+20,yy+35));draw.text((xx,yy+291),label,font=small,fill='#b6c5d5')
    out.save(root/'comparison.png')
